arguments.command:
python3 -c "
import json

with open('/app/resources/treasury_bulletin_1948_03.json') as f:
    data = json.load(f)

# Navigate to find tables
def find_tables(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            find_tables(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:3]):
            find_tables(item, f'{path}[{i}]')
    elif 'table' in str(path).lower() or 'Table' in str(obj):
        print(f'{path}: {type(obj)}')

find_tables(data)
"
